"""Photograph each object from its best view, cropped around its box, for a by-eye type review.

    python capture.py START END
"""

import io
import json
import sys
from pathlib import Path

from PIL import Image, ImageDraw
from playwright.sync_api import sync_playwright

S = Path("/tmp/claude-1000/-home-viktor-trilar-Projects-Newbies/6293938d-e68f-4310-92b7-6bf722e3d028/scratchpad")
OUT = S / "review" / "tiles"
OUT.mkdir(parents=True, exist_ok=True)
URL = "http://127.0.0.1:8524/?tablet=0&lod=0"
ARGS = ["--no-sandbox", "--ignore-gpu-blocklist", "--enable-gpu", "--use-angle=vulkan", "--enable-features=Vulkan"]
ids = json.load(open(S / "review" / "ids.json"))[int(sys.argv[1]) : int(sys.argv[2])]

# Place the camera at the object's best view, closer for small objects, and return its box on screen.
PLACE = """async (id) => {
  const v = window.plantViewer;
  const o = v.objects.find((x) => x.asset.object_id === id);
  const T = o.box.parent;
  const V3 = o.center.constructor;
  const c = T.localToWorld(o.center.clone());
  const a = o.asset;
  const size = Math.max(...[0, 1, 2].map((i) => Math.abs(a.bbox_max[i] - a.bbox_min[i])));
  const reply = await fetch(`/api/objects/${id}/view`).then((r) => r.json());
  let eye;
  if (reply.from) {
    eye = T.localToWorld(new V3(...reply.from));
    eye.y += 1.6;
  } else {
    eye = c.clone().add(new V3(0, 0.6, 1.5));
  }
  const want = Math.min(Math.max(size * 1.8, 0.9), 3.5);
  const dir = eye.clone().sub(c);
  if (dir.length() > want) eye = c.clone().add(dir.normalize().multiplyScalar(want));
  v.camera.position.copy(eye);
  v.camera.lookAt(c);
  v.camera.updateMatrixWorld();
  v.pacing.wake();
  const xs = [], ys = [];
  for (const x of [a.bbox_min[0], a.bbox_max[0]])
    for (const y of [a.bbox_min[1], a.bbox_max[1]])
      for (const z of [a.bbox_min[2], a.bbox_max[2]]) {
        const p = T.localToWorld(new V3(x, y, z)).project(v.camera);
        xs.push(((p.x + 1) / 2) * innerWidth);
        ys.push(((1 - p.y) / 2) * innerHeight);
      }
  return [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)];
}"""

with sync_playwright() as p:
    browser = p.chromium.launch(executable_path="/snap/bin/chromium", headless=True, args=ARGS)
    page = browser.new_context(viewport={"width": 1280, "height": 800}).new_page()
    page.set_default_timeout(120000)
    page.goto(URL)
    page.wait_for_function("window.plantViewer !== undefined")
    page.wait_for_timeout(5000)
    # Nothing but the room: no frames, labels, panels or badges.
    page.add_style_tag(
        content="#plan,#hud,#buttons,#alert-badges,#labels,.label,#info,#tour,#copilot{display:none!important}"
    )
    page.evaluate("document.getElementById('boxes').click()")
    for object_id in ids:
        box = page.evaluate(PLACE, object_id)
        page.wait_for_timeout(1100)
        shot = Image.open(io.BytesIO(page.screenshot())).convert("RGB")
        x0, y0, x1, y1 = box
        w, h = x1 - x0, y1 - y0
        pad = max(w, h) * 0.35 + 40
        crop = (max(x0 - pad, 0), max(y0 - pad, 0), min(x1 + pad, 1280), min(y1 + pad, 800))
        if crop[2] - crop[0] < 60 or crop[3] - crop[1] < 60:
            crop = (0, 0, 1280, 800)
        draw = ImageDraw.Draw(shot)
        draw.rectangle([max(x0, 1), max(y0, 1), min(x1, 1278), min(y1, 798)], outline=(255, 40, 40), width=2)
        shot.crop(crop).save(OUT / f"{object_id}.jpg", quality=85)
        print(object_id, flush=True)
    browser.close()

